216	export async function adminSendPasswordReset(userId: string) {
217	  const admin = await requireAdmin();
218	  const user = await db.user.findUnique({ where: { id: userId } });
219	  if (!user) throw new Error("User not found");
220	  const { randomBytes, createHash } = await import("node:crypto");
221	  const token = randomBytes(32).toString("base64url");
222	  const tokenHash = createHash("sha256").update(token).digest("hex");
223	  await db.passwordResetToken.create({
224	    data: { userId: user.id, tokenHash, expiresAt: new Date(Date.now() + 3600_000) },
225	  });
226	  const { sendMail, emails } = await import("./mailer");
227	  const link = `${process.env.APP_URL ?? "https://nxeon.cloud"}/reset-password?token=${token}`;
228	  const tpl = emails.passwordReset(link);
229	  // CRITICAL (see above): support has just told the customer "check your email".
230	  // A preference must not be able to make that a lie.
231	  if (await mayDeliverTo(user.id, "password_reset", "email")) {
232	    await sendMail({ to: user.email, subject: tpl.subject, html: tpl.html });
233	  }
234	  await db.auditLog.create({ data: { userId: admin.id, action: "admin.password_reset_sent", detail: user.email } });
235	}
