238	
239	export async function impersonateUser(userId: string) {
240	  const admin = await requireAdmin();
241	  const target = await db.user.findUnique({ where: { id: userId } });
242	  if (!target || target.role === "ADMIN") throw new Error("Cannot impersonate this account");
243	  await setImpersonation(userId);
244	  await db.auditLog.create({
245	    data: { userId: admin.id, action: "admin.impersonate_start", detail: `${target.email}` },
246	  });
247	  redirect("/dashboard");
248	}
