24	/**
25	 * SMTP config comes from the Setting table (admin-editable) with env fallback.
26	 * Keys: smtp_host, smtp_port, smtp_user, smtp_pass, smtp_from, smtp_secure.
27	 * If nothing is configured, falls back to a local sendmail/Postfix relay on :25.
28	 */
29	/**
30	 * The stored SMTP password, decrypted — tolerating a LEGACY plaintext row.
31	 *
32	 * `smtp_pass` is now written through `encryptSecret` (iv:tag:ciphertext), but a
33	 * value saved before that change is bare plaintext. `decryptSecret` returns null
34	 * on a value that is not in the encrypted shape, so a null result means "this was
35	 * never encrypted" — fall back to the raw stored value. Once an operator re-saves
36	 * the SMTP settings, the row is encrypted and this fallback stops being taken.
37	 */
38	function smtpPassPlain(stored: string | undefined): string {
39	  if (!stored) return "";
40	  const dec = decryptSecret(stored);
41	  return dec ?? stored;
42	}
43	
44	async function loadSmtp() {
45	  const rows = await db.setting.findMany({
46	    where: { key: { in: ["smtp_host", "smtp_port", "smtp_user", "smtp_pass", "smtp_from", "smtp_secure"] } },
47	  });
48	  const s = Object.fromEntries(rows.map((r) => [r.key, r.value]));
49	  const host = s.smtp_host || process.env.SMTP_HOST || "";
50	  const from = s.smtp_from || process.env.SMTP_FROM || `Nxeon <no-reply@${(process.env.APP_URL ?? "localhost").replace(/^https?:\/\//, "")}>`;
51	  return {
52	    host,
53	    port: Number(s.smtp_port || process.env.SMTP_PORT || 587),
54	    user: s.smtp_user || process.env.SMTP_USER || "",
55	    pass: smtpPassPlain(s.smtp_pass) || process.env.SMTP_PASS || "",
56	    secure: (s.smtp_secure ?? process.env.SMTP_SECURE) === "true",
57	    from,
58	  };
59	}
