120	export type SendMailOpts = {
121	  to: string;
122	  /** Optional Reply-To (e.g. route a contact-form reply straight to the sender). */
123	  replyTo?: string;
124	  /** Explicit subject. Optional when `template` is provided. */
125	  subject?: string;
126	  /** Explicit pre-rendered HTML. Optional when `template` is provided. */
127	  html?: string;
128	  text?: string;
129	  /** DB template key — when set (and no explicit `html`), the body is rendered via `renderTemplate`. */
130	  template?: string;
131	  /** Variables for `{{placeholders}}` when rendering from a template. */
132	  vars?: Record<string, unknown>;
133	  /** Attribution for the EmailLog row. */
134	  userId?: string | null;
135	  /** When set, attaches the invoice (auto for receipt/invoice_new/renewal_reminder templates). */
136	  invoiceId?: string;
137	  /** Extra attachments. */
138	  attachments?: MailAttachment[];
139	  /**
140	   * What KIND of message this is, for the notification-preference policy in
141	   * `lib/prefs.ts`. Supply it together with `userId` and this function enforces
142	   * the customer's choice centrally — see the gate below.
143	   *
144	   * Omitting it means "always send", which is the safe default: a message must
145	   * never be dropped because someone forgot to classify it.
146	   */
147	  kind?: NotifyKind;
148	};
149	
150	/**
151	 * Send an email. Never throws — logs and returns false on failure so callers
152	 * don't break flows. EVERY attempt is written to `EmailLog` (SENT on success,
153	 * FAILED + error otherwise) for the admin Logs viewer.
154	 *
155	 * NOTIFICATION PREFERENCES are enforced HERE, not at the call sites.
156	 * `User.notificationPrefs` was a column the customer edited and nothing read, so
157	 * turning off "email me about billing" changed nothing. Gating each send site
158	 * individually would have fixed today's sites and left every future one to
159	 * re-introduce the bug; gating centrally means a new send site inherits the
160	 * policy automatically and per-site checks become defence in depth.
161	 *
162	 * Two deliberate properties, both fail-open:
163	 *   - no `kind` (or no `userId`) → send. Unclassified is never silenced.
164	 *   - `mayDeliverTo` returns true for anything non-suppressible without touching
165	 *     the database, and also on a lookup error. A payment-failure or suspension
166	 *     warning must not be lost because a preference read failed.
167	 */
168	export async function sendMail(opts: SendMailOpts): Promise<boolean> {
169	  // Preference gate. CRITICAL kinds (payment failed, suspension, security
170	  // changes, data loss…) are declared non-suppressible in lib/prefs.ts and short
171	  // -circuit to true, so this costs nothing on the paths that matter most.
172	  if (opts.kind && opts.userId) {
173	    const allowed = await mayDeliverTo(opts.userId, opts.kind, "email");
174	    if (!allowed) {
175	      console.log(`[mail] suppressed ${opts.kind} to user ${opts.userId} by preference`);
176	      return false;
177	    }
178	  }
179	
180	  // Resolve subject/html: prefer explicit values, otherwise render the template.
181	  let subject = opts.subject ?? "";
182	  let html = opts.html ?? "";
183	  const templateKey = opts.template ?? null;
184	
185	  if (templateKey && !opts.html) {
186	    const rendered = await renderTemplate(templateKey, opts.vars ?? {});
187	    subject = opts.subject ?? rendered.subject;
188	    html = rendered.html;
189	  }
190	
191	  // Assemble attachments (invoice auto-attaches for the relevant templates).
192	  const attachments: MailAttachment[] = [...(opts.attachments ?? [])];
193	  const wantInvoice = opts.invoiceId && (!templateKey || INVOICE_ATTACH_TEMPLATES.has(templateKey));
194	  if (wantInvoice && opts.invoiceId) {
195	    const att = await invoiceAttachment(opts.invoiceId);
196	    if (att) attachments.push(att);
197	  }
198	
199	  try {
200	    const c = await loadSmtp();
201	    if (!c.host && process.env.NXEON_LOCAL_MAIL !== "1") {
202	      console.warn("[mailer] not configured — skipping email:", subject);
203	      await recordEmail(opts.to, subject, templateKey, html, "FAILED", "SMTP not configured", opts.userId);
204	      return false;
205	    }
206	    const t = transport(c);
207	    await t.sendMail({
208	      from: c.from,
209	      to: opts.to,
210	      replyTo: opts.replyTo || undefined,
211	      subject,
212	      html,
213	      text: opts.text ?? html.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim(),
214	      attachments: attachments.length ? attachments : undefined,
215	    });
216	    await recordEmail(opts.to, subject, templateKey, html, "SENT", null, opts.userId);
217	    return true;
218	  } catch (e) {
219	    console.error("[mailer] send failed:", e);
220	    await recordEmail(opts.to, subject, templateKey, html, "FAILED", String((e as Error)?.message ?? e), opts.userId);
221	    return false;
222	  }
223	}
